import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {parseCsv,validateTargetIdentityReconciliation} from './verify-target-identity-reconciliation.mjs';
const fixture=JSON.parse(fs.readFileSync('docs/data/target-identity-reconciliation.json','utf8')),tkb=JSON.parse(fs.readFileSync('docs/data/target-knowledge-base.json','utf8')),rows=parseCsv(fs.readFileSync('data/analytics/metadata/session-scientific-metadata.csv','utf8')),clone=x=>structuredClone(x);
const rejects=(mutate,pattern,mutateRows)=>{const x=clone(fixture),r=clone(rows);mutate(x);if(mutateRows)mutateRows(r);assert.match(validateTargetIdentityReconciliation(x,tkb,r).join('\n'),pattern);};
test('accepted bounded F3 reconciliation validates',()=>assert.deepEqual(validateTargetIdentityReconciliation(fixture,tkb,rows),[]));
test('rejects authority escalation',()=>rejects(x=>x.authority='authoritative',/authority must remain projection/));
test('rejects source contract structural widening',()=>rejects(x=>x.source_contract.extra=true,/exact bounded F3 source contract/));
test('rejects PARTIAL metadata as validating evidence',()=>rejects(x=>{x.matches[1].session_ids=['2026-08-10_2026-08-11'];x.matches[1].source_refs=['analytics-metadata:2026-08-10_2026-08-11'];},/complete eligible REGISTERED evidence set/));
test('rejects omitted eligible REGISTERED evidence',()=>rejects(x=>{x.matches[0].session_ids=x.matches[0].session_ids.slice(0,2);x.matches[0].source_refs=x.matches[0].source_refs.slice(0,2);},/complete eligible REGISTERED evidence set/));
test('rejects disagreement on formerly omitted eligible REGISTERED row',()=>rejects(()=>{},/target_id disagreement/,r=>{r.find(x=>x.session_id==='2026-07-16_2026-07-17').target_id='TGT-OTHER';}));
test('rejects canonical name disagreement by completeness loss',()=>rejects(()=>{},/complete eligible REGISTERED evidence set/,r=>{r.find(x=>x.session_id==='2026-08-15_2026-08-16').target_name='M27';}));
test('rejects arbitrary alias without governed evidence',()=>rejects(x=>x.matches[1].aliases=['Dumbbell Nebula'],/aliases require explicit governed alias evidence/));
test('rejects source ref misbinding',()=>rejects(x=>x.matches[0].source_refs[0]='analytics-metadata:wrong',/source_refs must bind exactly/));
test('rejects existing but wrong Citation binding',()=>rejects(x=>x.matches[0].citation_refs[0]='CIT-TIR-2026-08-14@1.0',/Citation refs must bind exactly/));
test('rejects Provenance input misbinding',()=>rejects(x=>x.provenance_records[0].input_refs=x.provenance_records[0].input_refs.slice(0,2),/Provenance inputs must equal/));
test('rejects Provenance output misbinding',()=>rejects(x=>x.provenance_records[0].output_ref='target-id-map:dsg-target:ldn-1320=TGT-OTHER',/Provenance output misbound/));
test('rejects Provenance Citation misbinding',()=>rejects(x=>x.provenance_records[0].citation_refs[0]='CIT-TIR-2026-08-14@1.0',/Provenance Citations misbound/));
test('rejects identifier reused by another target key',()=>rejects(x=>x.matches[1].target_id=x.matches[0].target_id,/maps to multiple target keys/));
test('rejects F2 canonical identity mutation',()=>rejects(x=>x.matches[0].canonical_name='LDN1320',/canonical name must preserve F2 identity/));
test('rejects match bound expansion',()=>rejects(x=>x.matches=[...x.matches,...x.matches,...x.matches],/match bound exceeded/));
test('rejects malformed conflict missing required fields',()=>rejects(x=>x.conflicts=[{conflict_id:'CONFLICT-TKB-X',target_key:'dsg-target:ldn-1320',reason:'TARGET_ID_DISAGREEMENT',identity_state:'conflicted',method_id:'BKL035-F3-EXACT-ID-RECONCILIATION-1'}],/structure invalid/));
test('rejects malformed conflict candidate cardinality',()=>rejects(x=>x.conflicts=[{conflict_id:'CONFLICT-TKB-X',target_key:'dsg-target:ldn-1320',reason:'TARGET_ID_DISAGREEMENT',candidate_target_ids:['TGT-X'],session_ids:['2026-07-14_2026-07-15'],identity_state:'conflicted',citation_refs:['CIT-TIR-2026-07-14@1.0'],provenance_refs:['PRV-TIR-LDN1320@1.0'],method_id:'BKL035-F3-EXACT-ID-RECONCILIATION-1'}],/candidate_target_ids invalid/));
